// Writes js/levels.js: the fixed content (Journey stages, challenges, the
// lesson grove) as generateLevel makes it, so the engine client never
// generates it at play time. Run after changing content generation; tests
// (tests/content.test.mjs) check the table against generateLevel.
import { writeFileSync } from 'node:fs';
import { fixedSources, generateLevel } from '../js/content.js';

const out = {};
for (const [key, seed, params] of fixedSources()) out[key] = generateLevel(seed, params);
writeFileSync(new URL('../js/levels.js', import.meta.url),
  '// Generated by tools/gen-levels.mjs — do not edit.\n// The fixed content as js/content.js generateLevel makes it.\nexport const FIXED = ' + JSON.stringify(out) + ';\n');
console.log(Object.keys(out).length, 'levels');
